export type RendererId = "three-r3f" | "babylon";

export type LifecycleStatus =
  | "probing"
  | "ready"
  | "unavailable"
  | "context-lost"
  | "disposed";

export type WebGl2Status = "unknown" | "available" | "unavailable";

export interface BenchState {
  readonly rendererId: RendererId;
  readonly lifecycle: LifecycleStatus;
  readonly webgl2: WebGl2Status;
  readonly generation: number;
}

export type BenchAction =
  | { readonly type: "probe-complete"; readonly webgl2: boolean }
  | { readonly type: "context-lost" }
  | { readonly type: "dispose" }
  | {
      readonly type: "recreate";
      readonly rendererId: RendererId;
      readonly webgl2: boolean;
    };

export const createBenchState = (rendererId: RendererId): BenchState => ({
  rendererId,
  lifecycle: "probing",
  webgl2: "unknown",
  generation: 0,
});

export const reduceBenchState = (
  state: BenchState,
  action: BenchAction,
): BenchState => {
  switch (action.type) {
    case "probe-complete":
      return {
        ...state,
        lifecycle: action.webgl2 ? "ready" : "unavailable",
        webgl2: action.webgl2 ? "available" : "unavailable",
      };
    case "context-lost":
      return state.lifecycle === "ready"
        ? { ...state, lifecycle: "context-lost" }
        : state;
    case "dispose":
      return state.lifecycle === "disposed"
        ? state
        : { ...state, lifecycle: "disposed" };
    case "recreate":
      return {
        rendererId: action.rendererId,
        lifecycle: action.webgl2 ? "ready" : "unavailable",
        webgl2: action.webgl2 ? "available" : "unavailable",
        generation: state.generation + 1,
      };
  }
};

