import { describe, expect, it } from "vitest";

import {
  createBenchState,
  reduceBenchState,
  type RendererId,
} from "../src/lifecycle";

const createState = (rendererId: RendererId = "three-r3f") =>
  createBenchState(rendererId);

describe("synthetic renderer evidence lifecycle", () => {
  it("reports a renderer as ready only after its actual WebGL2 probe succeeds", () => {
    const initial = createState();
    const ready = reduceBenchState(initial, {
      type: "probe-complete",
      webgl2: true,
    });

    expect(initial).toMatchObject({
      rendererId: "three-r3f",
      lifecycle: "probing",
      webgl2: "unknown",
      generation: 0,
    });
    expect(ready).toMatchObject({
      rendererId: "three-r3f",
      lifecycle: "ready",
      webgl2: "available",
      generation: 0,
    });
  });

  it("truthfully keeps an unavailable renderer unavailable when it receives a context-loss signal", () => {
    const unavailable = reduceBenchState(createState("babylon"), {
      type: "probe-complete",
      webgl2: false,
    });
    const afterLoss = reduceBenchState(unavailable, { type: "context-lost" });

    expect(unavailable).toMatchObject({
      rendererId: "babylon",
      lifecycle: "unavailable",
      webgl2: "unavailable",
    });
    expect(afterLoss).toEqual(unavailable);
  });

  it("records context loss only for a ready renderer and never revives it after disposal", () => {
    const ready = reduceBenchState(createState(), {
      type: "probe-complete",
      webgl2: true,
    });
    const lost = reduceBenchState(ready, { type: "context-lost" });
    const disposed = reduceBenchState(lost, { type: "dispose" });
    const disposedAgain = reduceBenchState(disposed, { type: "dispose" });
    const afterLateLoss = reduceBenchState(disposed, { type: "context-lost" });

    expect(lost.lifecycle).toBe("context-lost");
    expect(disposed.lifecycle).toBe("disposed");
    expect(disposedAgain).toBe(disposed);
    expect(afterLateLoss).toEqual(disposed);
  });

  it("recreates the selected engine as a new generation with its own probe result", () => {
    const disposed = reduceBenchState(createState(), { type: "dispose" });
    const recreated = reduceBenchState(disposed, {
      type: "recreate",
      rendererId: "babylon",
      webgl2: true,
    });

    expect(recreated).toEqual({
      rendererId: "babylon",
      lifecycle: "ready",
      webgl2: "available",
      generation: 1,
    });
  });

  it("does not label a recreated engine as ready when its next WebGL2 probe fails", () => {
    const recreated = reduceBenchState(createState("babylon"), {
      type: "recreate",
      rendererId: "three-r3f",
      webgl2: false,
    });

    expect(recreated).toEqual({
      rendererId: "three-r3f",
      lifecycle: "unavailable",
      webgl2: "unavailable",
      generation: 1,
    });
  });
});
